-- Anti-spoofing, network policy, review flags, alerts, presence challenge (FR-ATT-017, 018, 021, 023; ADR 019).
-- Part 1: generated by prisma migrate diff.

-- AlterTable
ALTER TABLE "attendance_sessions" ADD COLUMN     "challenge_id" UUID,
ADD COLUMN     "challenge_issued_at" TIMESTAMPTZ,
ADD COLUMN     "country_in" VARCHAR(2),
ADD COLUMN     "country_out" VARCHAR(2);

-- AlterTable
ALTER TABLE "organizations" ADD COLUMN     "att_allowed_cidrs" TEXT[] DEFAULT ARRAY[]::TEXT[],
ADD COLUMN     "att_allowed_countries" TEXT[] DEFAULT ARRAY[]::TEXT[],
ADD COLUMN     "att_flag_alert_threshold" INTEGER NOT NULL DEFAULT 3,
ADD COLUMN     "att_long_idle_alert_minutes" INTEGER NOT NULL DEFAULT 0,
ADD COLUMN     "att_no_clockin_reminder" BOOLEAN NOT NULL DEFAULT true,
ADD COLUMN     "att_presence_challenge" BOOLEAN NOT NULL DEFAULT false;

-- AlterTable
ALTER TABLE "users" ADD COLUMN     "last_country" VARCHAR(2),
ADD COLUMN     "last_country_at" TIMESTAMPTZ;

-- CreateTable
CREATE TABLE "attendance_flags" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "org_id" UUID NOT NULL,
    "user_id" UUID NOT NULL,
    "session_id" UUID,
    "work_date" VARCHAR(10) NOT NULL,
    "kind" VARCHAR(40) NOT NULL,
    "category" VARCHAR(20) NOT NULL,
    "details" JSONB NOT NULL DEFAULT '{}',
    "dedupe_key" VARCHAR(200) NOT NULL,
    "status" VARCHAR(20) NOT NULL DEFAULT 'OPEN',
    "resolution" VARCHAR(20),
    "resolution_note" TEXT,
    "resolved_by" UUID,
    "resolved_at" TIMESTAMPTZ,
    "user_comment" TEXT,
    "user_comment_at" TIMESTAMPTZ,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "attendance_flags_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "attendance_flags_org_id_status_created_at_idx" ON "attendance_flags"("org_id", "status", "created_at");

-- CreateIndex
CREATE INDEX "attendance_flags_org_id_user_id_created_at_idx" ON "attendance_flags"("org_id", "user_id", "created_at");

-- CreateIndex
CREATE UNIQUE INDEX "attendance_flags_org_id_dedupe_key_key" ON "attendance_flags"("org_id", "dedupe_key");

-- AddForeignKey
ALTER TABLE "attendance_flags" ADD CONSTRAINT "attendance_flags_org_id_fkey" FOREIGN KEY ("org_id") REFERENCES "organizations"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "attendance_flags" ADD CONSTRAINT "attendance_flags_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "attendance_flags" ADD CONSTRAINT "attendance_flags_resolved_by_fkey" FOREIGN KEY ("resolved_by") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "attendance_flags" ADD CONSTRAINT "attendance_flags_session_id_fkey" FOREIGN KEY ("session_id") REFERENCES "attendance_sessions"("id") ON DELETE SET NULL ON UPDATE CASCADE;


-- Part 2: hand-written.
ALTER TABLE attendance_flags
  ADD CONSTRAINT attendance_flags_category_check CHECK (category IN ('SPOOFING', 'NETWORK', 'DEVICE', 'OFFLINE', 'SESSION')),
  ADD CONSTRAINT attendance_flags_status_check CHECK (
    (status = 'OPEN' AND resolution IS NULL AND resolved_at IS NULL)
    OR (status = 'RESOLVED' AND resolution IN ('NO_ACTION', 'FOLLOW_UP') AND resolved_at IS NOT NULL AND length(btrim(coalesce(resolution_note, ''))) >= 3)),
  -- Nobody resolves a flag about themselves.
  ADD CONSTRAINT attendance_flags_not_self_check CHECK (resolved_by IS NULL OR resolved_by <> user_id),
  ADD CONSTRAINT attendance_flags_work_date_check CHECK (work_date ~ '^\d{4}-\d{2}-\d{2}$');
ALTER TABLE organizations
  ADD CONSTRAINT organizations_att_alerts_check CHECK (att_long_idle_alert_minutes BETWEEN 0 AND 1440 AND att_flag_alert_threshold BETWEEN 0 AND 100);
ALTER TABLE users ADD CONSTRAINT users_last_country_check CHECK (last_country IS NULL OR last_country ~ '^[A-Z0-9]{2}$');

ALTER TABLE attendance_flags ENABLE ROW LEVEL SECURITY;
ALTER TABLE attendance_flags FORCE ROW LEVEL SECURITY;
CREATE POLICY attendance_flags_org_policy ON attendance_flags FOR ALL
  USING (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid)
  WITH CHECK (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid);
-- Review evidence: resolved, never deleted by the app.
GRANT SELECT, INSERT, UPDATE ON attendance_flags TO hrvo_app;
REVOKE DELETE, TRUNCATE ON attendance_flags FROM hrvo_app;

-- A flag's session must be the same person's, in the same organisation.
CREATE FUNCTION fn_attendance_flag_session() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.session_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM attendance_sessions s WHERE s.id = NEW.session_id AND s.org_id = NEW.org_id AND s.user_id = NEW.user_id) THEN
    RAISE EXCEPTION 'attendance flag session must belong to the same user and organisation';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER trg_attendance_flag_session BEFORE INSERT OR UPDATE OF session_id ON attendance_flags
  FOR EACH ROW EXECUTE FUNCTION fn_attendance_flag_session();
